script:
frappe.ui.form.on('Opportunity Tracking', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Create Job Opening'), function() {
                frappe.new_doc('RPO Job Opening', {
                opportunity: frm.doc.name  // or use frm.doc.name if that's the Lead ID
                });
            });
        }
    }
});
